
// src/api/services/quizService.ts
import { apiClient } from '../client';
import { IQuiz } from '../../models/interfaces/quiz';
import { mapQuizResponse } from '../../models/mappers/quiz';

export class QuizService {
  private static instance: QuizService;
  private readonly baseUrl = '/api/quizzes';

  private constructor() {}

  public static getInstance(): QuizService {
    if (!QuizService.instance) {
      QuizService.instance = new QuizService();
    }
    return QuizService.instance;
  }

  public async getQuiz({ uuid, locale = 'en' }: { uuid: string, locale: string }): Promise<IQuiz> {
    const response = await apiClient.get<{ data: any }>(
      `${this.baseUrl}/${uuid}?locale=${locale}`
    );

    return mapQuizResponse(response.data);
  }
}

export const quizService = QuizService.getInstance();