import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { useTranslation } from 'react-i18next';
import { cn } from '@/lib/utils';
import { useToast } from '@/components/ui/use-toast';
import { IStep } from '@/models/interfaces/quiz';
import { ITipDataContent } from '@/models';
import { TipContent } from '@/components/common/TipContent';
import { useAnalytics } from '@/hooks/useAnalytics';

interface PricingProps {
  onComplete: (props: { paymentPlan: 'monthly' | 'yearly' }) => void;
  loading?: boolean;
  step: IStep;
}

interface PlanSelectionProps {
  onComplete: (props: { paymentPlan: 'monthly' | 'yearly' }) => void;
  onSelect: (plan: 'monthly' | 'yearly') => void;
  selectedPlan: 'monthly' | 'yearly';
  loading?: boolean;
}

const PlanSelection: React.FC<PlanSelectionProps> = ({ onComplete, onSelect, selectedPlan, loading = false }) => {
  const { t } = useTranslation();
  const { trackQuestionnaireCompleted } = useAnalytics();

  useEffect(() => {
    trackQuestionnaireCompleted();
  }, []);

  return (
    <div className="space-y-3">
      <button
        onClick={() => onSelect('yearly')}
        className={cn(
          'w-full text-left p-4 rounded-xl transition-all duration-300',
          selectedPlan === 'yearly'
            ? 'bg-gradient-to-r from-teal-400 to-blue-500 text-white'
            : 'bg-gray-50 text-gray-800 hover:bg-gray-100'
        )}
      >
        <div className="flex justify-between items-start">
          <div className="space-y-1">
            <div className="font-medium text-sm sm:text-base">{t('Start with Yearly for only')}</div>
            <div className="text-xs sm:text-sm opacity-80">{t('Billed annually $47.88')}</div>
          </div>
          <div className="flex flex-col items-end gap-2">
            <span className="font-bold text-sm sm:text-base">$3.99/{t('month')}</span>
            <span className="bg-red-400 text-white px-2 py-0.5 rounded-full text-xs sm:text-sm">
              {t('Save 33%')}
            </span>
          </div>
        </div>
      </button>

      <button
        onClick={() => onSelect('monthly')}
        className={cn(
          'w-full text-left p-4 rounded-xl transition-all duration-300',
          selectedPlan === 'monthly'
            ? 'bg-gradient-to-r from-teal-400 to-blue-500 text-white'
            : 'bg-gray-50 text-gray-800 hover:bg-gray-100'
        )}
      >
        <div className="flex justify-between items-center">
          <div className="space-y-1">
            <div className="font-medium text-sm sm:text-base">{t('Start with Monthly')}</div>
            <div className="text-xs sm:text-sm opacity-80">{t('Billed monthly')}</div>
          </div>
          <span className="font-bold text-sm sm:text-base">$5.99/{t('month')}</span>
        </div>
      </button>


      <motion.button
        whileHover={{ scale: 1.02 }}
        whileTap={{ scale: 0.98 }}
        onClick={() => onComplete({ paymentPlan: selectedPlan })}
        disabled={loading}
        className="w-full bg-gradient-to-r from-teal-400 to-blue-500 text-white py-3 rounded-xl
            font-bold text-sm sm:text-base transition-all duration-300 shadow-md hover:shadow-lg disabled:opacity-50
            disabled:cursor-not-allowed"
      >
        {loading ? (
          <div className="flex items-center justify-center gap-2">
            <div className="animate-spin rounded-full h-4 w-4 sm:h-5 sm:w-5 border-b-2 border-white" />
            {t('Processing...')}
          </div>
        ) : (
          t('Pay')
        )}
      </motion.button>
    </div>
  )
}

export const PricingSelectionV2: React.FC<PricingProps> = ({ onComplete, loading = false, step }) => {
  const { t } = useTranslation();
  const [selectedPlan, setSelectedPlan] = useState<'monthly' | 'yearly'>('monthly');

  const { toast, dismiss } = useToast();
  const tipContent = step.dataContent as ITipDataContent;

  const handleSubmit = () => {
    if (!loading) {
      onComplete({ paymentPlan: selectedPlan });

      let toastId: string;

      const dismissToast = () => {
        dismiss(toastId);
      };

      const toastInstance = toast({
        title: t('We\'re upgrading our payment system'),
        description: t('You\'ll be redirected to continue with your VitaWheel journey'),
        duration: 5000,
        action: (
          <button
            onClick={dismissToast}
            className="bg-teal-500 hover:bg-teal-600 text-white px-3 py-1 rounded-md text-sm font-medium transition-colors"
          >
            {t('Continue')}
          </button>
        )
      });

      toastId = toastInstance.id;

      // Auto-dismiss after 5 seconds
      setTimeout(dismissToast, 5000);
    }
  };

  return (
    <motion.div
      className="space-y-6 w-full max-w-md mx-auto px-4 sm:px-6"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
    >
      {/* Features */}
      <div className="space-y-3">
        <div className="flex items-center gap-3">
          <span className="text-teal-500 flex-shrink-0 text-xl">🌟</span>
          <span className="text-gray-800 text-sm sm:text-base text-center">
            {t('10 recommendations every week to\nimprove your life with VitaWheel')}
          </span>
        </div>

        <div className="flex items-center gap-3">
          <span className="text-teal-500 flex-shrink-0 text-xl">🚀</span>
          <span className="text-gray-800 text-sm sm:text-base text-center">
            {t('Small steps – big changes!')}
          </span>
        </div>

        <div className="flex items-center gap-3">
          <span className="text-teal-500 flex-shrink-0 text-xl">🎯</span>
          <span className="text-gray-800 text-sm sm:text-base text-center">
            {t('Track your goals, habits and balance')}
          </span>
        </div>
      </div>

      {/* Stats Box */}
      <div className="bg-teal-50 rounded-xl p-4 text-center">
        <p className="text-teal-600 text-sm sm:text-base text-center">
          {t('43.000+ people have already achieved harmony in their lives with VitaWheel. Move towards the best version of yourself!')}
        </p>
      </div>

      <div className="bg-gradient-to-r from-teal-50 to-blue-50 rounded-xl p-4 flex items-center gap-3">
        <div className="flex-shrink-0 text-2xl">✨</div>
        <div className="space-y-1">
          <p className="font-medium text-gray-800">Try VitaWheel Risk-Free for 14 Days</p>
          <p className="text-sm text-gray-600">
            {t('Start your journey to a better life today! If you don\'t see positive changes, get a 100% refund – no questions asked.')}
          </p>
        </div>
      </div>

      <PlanSelection
        onComplete={handleSubmit}
        onSelect={setSelectedPlan}
        selectedPlan={selectedPlan}
        loading={loading}
      />

      {tipContent && (
        <>
          <TipContent tipContent={tipContent} />

          <div className="bg-gradient-to-r from-teal-50 to-blue-50 rounded-xl p-4 flex items-center gap-3">
            <div className="flex-shrink-0 text-2xl">✨</div>
            <div className="space-y-1">
              <p className="font-medium text-gray-800">Try VitaWheel Risk-Free for 14 Days</p>
              <p className="text-sm text-gray-600">
                {t('Start your journey to a better life today! If you don\'t see positive changes, get a 100% refund – no questions asked.')}
              </p>
            </div>
          </div>

          <PlanSelection
            onComplete={handleSubmit}
            onSelect={setSelectedPlan}
            selectedPlan={selectedPlan}
            loading={loading}
          />
        </>
      )}
    </motion.div>
  );
};
