// src/api/services/participantService.ts
import { apiClient } from '../client';
import { IQuizParticipant } from '../../models/interfaces/quiz-participant';
import { STORAGE_KEYS } from '../config';
import { mapQuizParticipantResponse } from '../../models/mappers/quiz-participant';

export class ParticipantService {
  private static instance: ParticipantService;

  private constructor() {}

  public static getInstance(): ParticipantService {
    if (!ParticipantService.instance) {
      ParticipantService.instance = new ParticipantService();
    }
    return ParticipantService.instance;
  }

  public async createParticipant(quizUuid: string): Promise<IQuizParticipant> {
    const response = await apiClient.post<{ data: any }>(
      `/api/quizzes/${quizUuid}/participants`,
      {
        data: {
          uuid: crypto.randomUUID(),
        }
      }
    );
    const participant = mapQuizParticipantResponse(response.data);
    this.saveParticipantToStorage(participant);
    return participant;
  }

  public async updateParticipantEmail(
    quizUuid: string,
    participantUuid: string,
    email: string
  ): Promise<IQuizParticipant> {
    const response = await apiClient.put<{ data: any }>(
      `/api/quizzes/${quizUuid}/participants/${participantUuid}/email`,
      {
        data: { email }
      }
    );
    const participant = mapQuizParticipantResponse(response.data);
    return participant;
  }

  public async submitAnswer(
    quizUuid: string,
    participantUuid: string,
    questionId: number,
    selectedAnswer: string
  ): Promise<IQuizParticipant> {
    const response = await apiClient.post<{ data: any }>(
      `/api/quizzes/${quizUuid}/participants/${participantUuid}/answer`,
      {
        data: {
          questionId,
          selectedAnswer
        }
      }
    );
    return mapQuizParticipantResponse(response.data);
  }

  public async updateProgress(
    quizUuid: string,
    participantUuid: string,
    stepNumber: number,
    questionId?: number,
    answerId?: number
  ): Promise<IQuizParticipant> {
    const response = await apiClient.put<{ data: any }>(
      `/api/quizzes/${quizUuid}/participants/${participantUuid}/progress`,
      {
        data: {
          stepNumber,
          questionId,
          answerId
        }
      }
    );
    return mapQuizParticipantResponse(response.data);
  }

  public async updatePaymentPlan(
    quizUuid: string,
    participantUuid: string,
    paymentPlan: 'monthly' | 'yearly'
  ): Promise<void> {
    await apiClient.put<{ data: any }>(
      `/api/quizzes/${quizUuid}/participants/${participantUuid}/payment-plan`,
      {
        data: { paymentPlan }
      }
    )
  }

  public async getParticipant(
    quizUuid: string,
    participantUuid: string
  ): Promise<IQuizParticipant> {
    const response = await apiClient.get<{ data: any }>(
      `/api/quizzes/${quizUuid}/participants/${participantUuid}`
    );
    return mapQuizParticipantResponse(response.data);
  }

  public getStoredParticipant(): { participantUuid: string, participantQuizUuid: string } | null {
    const data = localStorage.getItem(STORAGE_KEYS.PARTICIPANT);
    return data ? JSON.parse(data) : null;
  }

  public saveParticipantToStorage(participant: IQuizParticipant): void {
    localStorage.setItem(STORAGE_KEYS.PARTICIPANT, JSON.stringify({
      participantUuid: participant.uuid,
      participantQuizUuid: participant.quiz.uuid
    }));
  }

  public clearParticipantFromStorage(): void {
    localStorage.removeItem(STORAGE_KEYS.PARTICIPANT);
  }

  public async getOrCreateParticipant(quizUuid: string): Promise<IQuizParticipant> {
    const storedData = this.getStoredParticipant();

    if (!storedData || storedData.participantQuizUuid !== quizUuid) {
      return this.createParticipant(quizUuid);
    }

    try {
      const participant = await this.getParticipant(quizUuid, storedData.participantUuid);
      return participant;
    } catch (error) {
      this.clearParticipantFromStorage();
      return this.createParticipant(quizUuid);
    }
  }
}

export const participantService = ParticipantService.getInstance();