import { useEffect } from "react";
import { getConfigValue } from "../api/config";
import { useQuiz } from "./useQuiz";

import "../global.d";

declare global {
  interface Window {
    dataLayer: any[];
    gtag: (
      args_0: string | Date,
      args_1: string | Date,
      ...args_2: any[]
    ) => void;
    fbq: (
      event: string,
      eventName: string,
      params?: Record<string, any>
    ) => void;
  }
}

export const useAnalytics = () => {
  const { currentQuizId } = useQuiz();

  useEffect(() => {
    const gaScript = document.createElement("script");

    gaScript.async = true;
    gaScript.src = "https://www.googletagmanager.com/gtag/js?id=G-ZG26M5SPN8";
    document.head.appendChild(gaScript);

    window.dataLayer = window.dataLayer || [];
    window.gtag = function () {
      window.dataLayer.push(arguments);
    };

    try {
      window.gtag("js", new Date());

      window.gtag("config", "G-ZG26M5SPN8", {
        user_id: localStorage.getItem("user_email") || undefined,
        send_page_view: true,
      });

      window.gtag("set", "user_properties", {
        quiz_id: currentQuizId,
        role: getConfigValue("role", "user"),
      });
    } catch (error) {
      console.error("Failed to initialize GA:", error);
    }

    return () => {
      document.head.removeChild(gaScript);
    };
  }, [currentQuizId]);

  const trackEvent = (eventName: string, data: Record<string, any>) => {
    try {
      const userEmail = localStorage.getItem("user_email");
      const commonParams = {
        event_category: "Questionnaire",
        event_label: "",
        user_id: userEmail,
        quiz_id: currentQuizId,
        send_to: "G-ZG26M5SPN8",
      };

      window.gtag("event", eventName, {
        ...commonParams,
        ...data,
      });
    } catch (error) {
      console.error(`Failed to track event ${eventName}:`, error);
    }
  };

  const trackQuestionnaireStarted = () => {
    trackEvent("questionnaire_started", {
      component: "WelcomeToVitawell",
      event_label: "Quiz Started",
    });
  };

  const trackQuestionAnswered = (
    questionNumber: number,
    questionText: string
  ) => {
    trackEvent("question_answered", {
      component: "Question",
      event_label: `Question ${questionNumber}: ${questionText}`,
      question_number: questionNumber,
      question_text: questionText,
    });
  };

  const trackQuestionnaireCompleted = () => {
    trackEvent("questionnaire_completed", {
      component: "Submit",
      event_label: "Quiz Completed",
    });
  };

  const trackEmailSubmitted = (email: string) => {
    trackEvent("email_submitted", {
      component: "Submit",
      event_label: "Email Submitted",
      email_provided: true,
    });

    try {
      if (window.fbq) {
        window.fbq("track", "Lead", {
          email,
        });
      }
    } catch (error) {
      console.error("Failed to track Facebook event:", error);
    }
  };

  const trackPricingSelected = (paymentPlan: "monthly" | "yearly") => {
    trackEvent("pricing_selected", {
      component: "PricingSelection",
      event_label: "Pricing Selected",
      payment_plan: paymentPlan,
    });

    try {
      if (window.fbq) {
        const value = paymentPlan === "monthly" ? 5.99 : 47.88;
        window.fbq("track", "Purchase", {
          value,
          currency: "USD",
        });
      }
    } catch (error) {
      console.error("Failed to track Facebook Purchase event:", error);
    }
  };

  return {
    trackEvent,
    trackQuestionnaireStarted,
    trackQuestionAnswered,
    trackQuestionnaireCompleted,
    trackEmailSubmitted,
    trackPricingSelected,
  };
};
