import React from 'react';
import { useTranslation } from 'react-i18next';
import { QuizStepComponentProps } from '../QuizContainer';

export const Question: React.FC<QuizStepComponentProps> = ({
  step,
  onComplete,
  loading = false
}) => {
  const { t } = useTranslation();

  if (!step.question) {
    return (
      <div className="text-center text-red-500">
        {t('Question data not found')}
      </div>
    );
  }

  return (
    <div className="w-full flex flex-col h-full">
      {/* Top spacing div */}
      <div className="flex-1" />

      {/* Question Header */}
      <div className="px-4 mb-8">
        <h2 className="text-2xl md:text-3xl font-bold text-center text-gray-800">
          {step.question.content}
        </h2>
      </div>

      {/* Answers Section */}
      <div className="w-full px-4 space-y-3 mb-8">
        {step.question.answers.map((answer) => (
          <button
            key={answer.id}
            onClick={() => onComplete({ answerId: answer.id })}
            disabled={loading}
            className="w-full bg-white border-2 border-[#46bdc6] text-gray-700 py-4 px-6 rounded-xl
              font-medium text-lg transition-all duration-300 hover:bg-[#46bdc6]/5
              hover:border-[#46bdc6] hover:text-[#46bdc6] shadow-md hover:shadow-lg
              disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {answer.text}
          </button>
        ))}
      </div>

      {/* Bottom spacing div */}
      <div className="flex-1" />
    </div>
  );
};