import React from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { ITipDataContent } from '@/models';

interface TipContentProps {
  tipContent: ITipDataContent;
}

export const TipContent: React.FC<TipContentProps> = ({ tipContent }) => {
  return (
    <AnimatePresence mode="wait">
      {tipContent.tips.map((tip, index) => (
        <React.Fragment key={index}>

          <motion.div
            className="bg-white rounded-xl p-4 shadow-md"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: index * 0.2 }}
          >
            <div className="flex items-start gap-3">
              <span className="text-2xl flex-shrink-0">{tip.icon}</span>
              <div className="space-y-2">
                <h3 className="text-xl font-bold text-gray-800">{tip.title}</h3>
                <p className="text-gray-600 text-sm">{tip.description}</p>
              </div>
            </div>
          </motion.div>

          {tip.image && (
            <motion.div
              className="bg-white rounded-xl shadow-md"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.2 + 0.1 }}
            >
              <motion.img
                src={tip.image.src}
                alt={tip.image.alt}
                className="w-full h-auto rounded-lg"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: index * 0.2 + 0.2 }}
              />
            </motion.div>
          )}
        </React.Fragment>
      ))}
    </AnimatePresence>
  );
};
