import React from 'react';
import { motion } from 'framer-motion';
import { useTranslation } from 'react-i18next';
import { QuizStepComponentProps } from '../QuizContainer';
import { ITipDataContent } from '@/models/interfaces';
import { TipContent } from '@/components/common/TipContent';

export const Tip: React.FC<QuizStepComponentProps> = ({
  step,
  onComplete,
  loading = false,
  stepIndex,
  totalSteps,
}) => {
  const { t } = useTranslation();
  const tipContent = step.dataContent as ITipDataContent;

  if (!tipContent) {
    return null;
  }

  const remainingScreens = totalSteps - stepIndex - 3;

  return (
    <>
      <motion.div
        className="w-full max-w-md mx-auto space-y-6"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -20 }}
      >
        <TipContent tipContent={tipContent} />
        <div className="h-24" />
      </motion.div>

      {remainingScreens > 0 && (
        <motion.div
          className="fixed bottom-6 left-0 right-0 px-4 mx-auto max-w-sm"
          initial={{ y: 20 }}
          animate={{ y: 0 }}
          exit={{ y: 20 }}
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
        >
          <button
            onClick={() => onComplete({})}
            disabled={loading}
            className="w-full bg-gradient-to-r from-teal-400 to-blue-500 text-white py-3 px-6 rounded-xl font-medium text-lg shadow-lg hover:shadow-xl transition-all duration-300 disabled:opacity-50"
          >
            {t('{{count}} screens left', { count: remainingScreens })} →
          </button>
        </motion.div>
      )}
    </>
  );
};

